mapper.update:
UPDATE twin_card_mapping
SET card_status = #{status},
    last_modified_time = #{updateTime}
WHERE card_no = #{cardNo}

mapper.select:
SELECT DISTINCT e.user_id
FROM aro_access_log e
WHERE e.accessType = 1
  AND CAST(e.create_time AS DATETIME) >= #{todayStart}
  AND CAST(e.create_time AS DATETIME) < #{todayEnd}
  AND e.user_id IS NOT NULL
  AND TRIM(e.user_id) != ''
  AND NOT EXISTS (
      SELECT 1
      FROM aro_access_log out_log
      WHERE out_log.user_id = e.user_id
        AND out_log.accessType IN (2, 3)
        AND CAST(out_log.create_time AS DATETIME) > CAST(e.create_time AS DATETIME)
        AND CAST(out_log.create_time AS DATETIME) >= #{todayStart}
        AND CAST(out_log.create_time AS DATETIME) < #{todayEnd}
        AND (
            (out_log.room_id IS NOT NULL AND e.room_id IS NOT NULL AND out_log.room_id = e.room_id)
            OR (out_log.room_id IS NULL AND e.room_id IS NULL)
        )
  )
